        wr_prev <= IO_WR;
        IF (wr_prev = '0' AND IO_WR = '1' AND IO_ADDR = x"00E2") THEN
          IF DATAIN(0) = '1' THEN
            rom_en_i <= '0';
          END IF;
        END IF;
